    //     cache.delete(`${urlSeriesDetailed(novel.seriesId)}`)
    //     cache.delete(`${urlSearchSeries(novel.seriesTitle, 1)}`)
    // }
    sleepToast(`🧹 清除缓存\n\n📌 当前章节：${novel.title}\n\n已清除本章正文缓存，刷新正文以更新`, 5)
}

function sleepToast(text, second=0) {
    java.log(text)
    // java.toast(text)
    java.longToast(text)
    sleep(1000*second)
}

