            arr.forEach(x => {
                let k = e.select(`a[href='${x.url}'] .text`).text() + '';
                if (k) x.name = k;
                result[result.length] = JSON.stringify(x);
            });
        }
        result[result.length] = obj;
    }
}
//java.log(result);
result;

